{"command":"python -c "
import csv

# Read input stops
input_stops = {}
with open('outputs/t05_clean_stops.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        input_stops[row['stop_id']] = {
            'stop_name': row['stop_name'],
            'stop_lat': row['stop_lat'],
            'stop_lon': row['stop_lon']
        }

# Read output stops
output_stops = {}
with open('outputs/t06_stop_service_intensity.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        output_stops[row['stop_id']] = {
            'stop_name': row['stop_name'],
            'stop_lat': row['stop_lat'],
            'stop_lon': row['stop_lon']
        }

# Compare
mismatches = 0
for stop_id in input_stops:
    if stop_id not in output_stops:
        print(f'Missing stop: {stop_id}')
        mismatches += 1
    elif input_stops[stop_id] != output_stops[stop_id]:
        print(f'Mismatch for {stop_id}:')
        print(f'  Input: {input_stops[stop_id]}')
        print(f'  Output: {output_stops[stop_id]}')
        mismatches += 1

print(f'Total mismatches: {mismatches}')
""}

